<style>
.lmg-finance{min-height:100vh;background:#f5f5f3;padding:24px}.lmg-finance>.d-sm-flex,.lmg-finance>.d-flex:first-child,.lmg-finance>.container-fluid>h1{border-radius:26px;background:#18181b;color:#fff!important;padding:26px 30px;box-shadow:0 14px 32px rgba(24,24,27,.14)}.lmg-finance h1{font-size:28px;font-weight:700;letter-spacing:-.03em}.lmg-finance .row{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}.lmg-finance .col-xl-4,.lmg-finance .col-md-4{grid-column:span 4}.lmg-finance .col-xl-3,.lmg-finance .col-md-3{grid-column:span 3}.lmg-finance .col-md-2{grid-column:span 2}.lmg-finance .col-md-1{grid-column:span 1}.lmg-finance .col-md-6{grid-column:span 6}.lmg-finance .col-12{grid-column:1/-1}.lmg-finance .card{overflow:hidden;border:1px solid #e4e4e7!important;border-radius:18px;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.05)!important}.lmg-finance .card-header{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #f4f4f5;background:#fff!important;padding:16px 20px}.lmg-finance .card-body{padding:20px}.lmg-finance .card-footer{border-top:1px solid #f4f4f5;background:#fafafa;padding:14px 20px}.lmg-finance .table-responsive{overflow-x:auto}.lmg-finance .table{width:100%;border-collapse:collapse;white-space:nowrap}.lmg-finance .table th{border-bottom:1px solid #e4e4e7!important;background:#fafafa!important;padding:12px 14px;font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#71717a}.lmg-finance .table td{border-bottom:1px solid #f4f4f5!important;padding:13px 14px;font-size:13px;color:#3f3f46}.lmg-finance .table tr:hover td{background:#fafafa}.lmg-finance .form-control,.lmg-finance input,.lmg-finance select,.lmg-finance textarea{border:1px solid #d4d4d8!important;border-radius:11px!important;background:#fff;padding:9px 11px;font-size:13px;outline:none}.lmg-finance .form-control:focus,.lmg-finance input:focus,.lmg-finance select:focus,.lmg-finance textarea:focus{border-color:#18181b!important;box-shadow:0 0 0 1px #18181b}.lmg-finance label{display:block;margin-bottom:6px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#71717a}.lmg-finance .btn{display:inline-flex;align-items:center;justify-content:center;gap:5px;border:1px solid #d4d4d8;border-radius:10px;background:#fff;padding:8px 12px;font-size:12px;font-weight:700;color:#3f3f46;transition:.2s}.lmg-finance .btn:hover{transform:translateY(-1px);box-shadow:0 5px 15px rgba(0,0,0,.08)}.lmg-finance .btn-primary,.lmg-finance .btn-dark{border-color:#18181b!important;background:#18181b!important;color:#fff!important}.lmg-finance .btn-success{border-color:#bef264!important;background:#bef264!important;color:#18181b!important}.lmg-finance .btn-warning{border-color:#fde68a!important;background:#fffbeb!important;color:#a16207!important}.lmg-finance .btn-danger,.lmg-finance .btn-outline-danger{border-color:#fecdd3!important;background:#fff1f2!important;color:#be123c!important}.lmg-finance .badge{display:inline-flex;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:700}.lmg-finance .badge-success,.lmg-finance .bg-success{background:#ecfccb!important;color:#3f6212!important}.lmg-finance .badge-warning,.lmg-finance .bg-warning{background:#fef3c7!important;color:#92400e!important}.lmg-finance .badge-danger,.lmg-finance .bg-danger{background:#ffe4e6!important;color:#be123c!important}.lmg-finance .badge-secondary,.lmg-finance .bg-secondary{background:#f4f4f5!important;color:#52525b!important}.lmg-finance .text-success{color:#15803d!important}.lmg-finance .text-danger{color:#be123c!important}.lmg-finance .text-primary{color:#3f6212!important}.lmg-finance .text-muted{color:#71717a!important}.lmg-finance .font-weight-bold{font-weight:700}.lmg-finance .small{font-size:12px}.lmg-finance .d-flex,.lmg-finance .d-sm-flex,.lmg-finance .form-inline{display:flex}.lmg-finance .align-items-center,.lmg-finance .align-items-end{align-items:center}.lmg-finance .justify-content-between{justify-content:space-between}.lmg-finance .justify-content-end{justify-content:flex-end}.lmg-finance .text-center{text-align:center}.lmg-finance .text-right{text-align:right}.lmg-finance .w-100{width:100%}.lmg-finance .mb-0{margin-bottom:0}.lmg-finance .mb-1{margin-bottom:4px}.lmg-finance .mb-2{margin-bottom:8px}.lmg-finance .mb-3{margin-bottom:12px}.lmg-finance .mb-4{margin-bottom:20px}.lmg-finance .mt-3{margin-top:12px}.lmg-finance .mt-4{margin-top:20px}.lmg-finance .mr-1{margin-right:4px}.lmg-finance .mr-2{margin-right:8px}.lmg-finance .ml-2{margin-left:8px}.lmg-finance .modal{position:fixed!important;inset:0!important;z-index:100000!important;display:none;overflow:auto;background:rgba(9,9,11,.65);padding:20px;backdrop-filter:blur(5px)}.lmg-finance .modal.show{display:flex!important;align-items:center;justify-content:center}.lmg-finance .modal-dialog{width:100%;max-width:600px;margin:auto}.lmg-finance .modal-xl{max-width:1100px}.lmg-finance .modal-content{max-height:calc(100vh - 40px);overflow:auto;border-radius:22px;background:#fff;box-shadow:0 25px 60px rgba(0,0,0,.3)}.lmg-finance .modal-header,.lmg-finance .modal-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;border-color:#f4f4f5;padding:17px 21px}.lmg-finance .modal-body{padding:21px}.lmg-finance .close,.lmg-finance .btn-close{border:0!important;background:#f4f4f5!important;border-radius:9px!important;padding:6px 10px}.lmg-finance .pagination{display:flex;gap:5px;list-style:none}.lmg-finance .page-link{display:block;border:1px solid #e4e4e7;border-radius:8px;background:#fff;padding:6px 10px;font-size:12px;color:#52525b}.lmg-finance .page-item.active .page-link{background:#18181b;color:#fff}.lmg-finance .page-item.disabled{opacity:.4}@media(max-width:900px){.lmg-finance{padding:14px}.lmg-finance .row>[class*="col-"]{grid-column:1/-1}.lmg-finance>.d-sm-flex{display:flex;flex-direction:column;align-items:flex-start;gap:15px}}
</style>
<script>
document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('.lmg-finance');if(!root)return;const close=m=>{m?.classList.remove('show');if(!root.querySelector('.modal.show'))document.body.style.overflow=''};root.addEventListener('click',e=>{const opener=e.target.closest('[data-toggle="modal"]');if(opener){e.preventDefault();const modal=document.querySelector(opener.dataset.target);if(window.jQuery&&modal)window.jQuery(modal).trigger(window.jQuery.Event('show.bs.modal',{relatedTarget:opener}));modal?.classList.add('show');document.body.style.overflow='hidden'}const dismiss=e.target.closest('[data-dismiss="modal"],[data-bs-dismiss="modal"]');if(dismiss){e.preventDefault();close(dismiss.closest('.modal'))}if(e.target.classList.contains('modal'))close(e.target)});document.addEventListener('keydown',e=>{if(e.key==='Escape')close(root.querySelector('.modal.show'))})});
</script>
